PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS node_types(id TEXT PRIMARY KEY, domain TEXT NOT NULL, description TEXT, attributes_schema TEXT CHECK(attributes_schema IS NULL OR json_valid(attributes_schema)));
CREATE TABLE IF NOT EXISTS edge_types(id TEXT PRIMARY KEY, description TEXT, directed INTEGER NOT NULL DEFAULT 1 CHECK(directed IN(0,1)));
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY, node_type TEXT NOT NULL REFERENCES node_types(id), name TEXT NOT NULL, purpose TEXT, description TEXT, lifecycle TEXT NOT NULL DEFAULT 'discovered' CHECK(lifecycle IN('proposed','discovered','designed','implemented','tested','operational','deprecated','unknown')), attributes TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(attributes)), created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_nodes_type ON nodes(node_type);
CREATE TABLE IF NOT EXISTS edges(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES nodes(id), target_id TEXT NOT NULL REFERENCES nodes(id), edge_type TEXT NOT NULL REFERENCES edge_types(id), status TEXT NOT NULL DEFAULT 'proposed', confidence REAL CHECK(confidence BETWEEN 0 AND 1), properties TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(properties)), valid_from TEXT, valid_to TEXT, UNIQUE(source_id,target_id,edge_type));
CREATE INDEX IF NOT EXISTS idx_edges_target ON edges(target_id);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, source_type TEXT NOT NULL, title TEXT NOT NULL, uri TEXT, source_date TEXT, retrieved_at TEXT, authority TEXT, checksum TEXT, raw_local_path TEXT, metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)));
CREATE TABLE IF NOT EXISTS source_excerpts(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), locator TEXT, excerpt TEXT NOT NULL, excerpt_hash TEXT);
CREATE TABLE IF NOT EXISTS claims(id TEXT PRIMARY KEY, subject_id TEXT REFERENCES nodes(id), predicate TEXT NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), epistemic_status TEXT NOT NULL CHECK(epistemic_status IN('confirmed','reported','inferred','proposed','disputed','superseded','unknown')), confidence REAL CHECK(confidence BETWEEN 0 AND 1), observed_at TEXT, valid_at TEXT, supersedes_id TEXT REFERENCES claims(id), notes TEXT);
CREATE TABLE IF NOT EXISTS claim_evidence(claim_id TEXT NOT NULL REFERENCES claims(id), source_id TEXT NOT NULL REFERENCES sources(id), excerpt_id TEXT REFERENCES source_excerpts(id), support TEXT NOT NULL DEFAULT 'supports' CHECK(support IN('supports','contradicts','context')), PRIMARY KEY(claim_id,source_id));
CREATE TABLE IF NOT EXISTS repositories(node_id TEXT PRIMARY KEY REFERENCES nodes(id), owner TEXT, repo_name TEXT, default_branch TEXT, visibility TEXT, last_scanned TEXT, canonical_role TEXT);
CREATE TABLE IF NOT EXISTS artifacts(node_id TEXT PRIMARY KEY REFERENCES nodes(id), repository_id TEXT REFERENCES nodes(id), repo_path TEXT, format TEXT, content_hash TEXT, version TEXT, last_verified TEXT);
CREATE TABLE IF NOT EXISTS interfaces(node_id TEXT PRIMARY KEY REFERENCES nodes(id), protocol TEXT, direction TEXT, contract_uri TEXT, version TEXT, auth_method TEXT);
CREATE TABLE IF NOT EXISTS integrations(node_id TEXT PRIMARY KEY REFERENCES nodes(id), source_system_id TEXT REFERENCES nodes(id), target_system_id TEXT REFERENCES nodes(id), interface_id TEXT REFERENCES nodes(id), transport TEXT, execution_owner_id TEXT REFERENCES nodes(id), failure_policy TEXT, validation_state TEXT NOT NULL DEFAULT 'unverified');
CREATE TABLE IF NOT EXISTS recipes(node_id TEXT PRIMARY KEY REFERENCES nodes(id), integration_id TEXT REFERENCES nodes(id), trigger_type TEXT, operation TEXT, determinism TEXT CHECK(determinism IN('deterministic','ai_assisted','hybrid','unknown')), idempotency_key TEXT, rollback_plan TEXT, test_ref TEXT);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, recipe_id TEXT REFERENCES nodes(id), started_at TEXT, finished_at TEXT, result TEXT, evidence_source_id TEXT REFERENCES sources(id), error_code TEXT, details TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details)));
CREATE TABLE IF NOT EXISTS variables(node_id TEXT PRIMARY KEY REFERENCES nodes(id), category TEXT, datatype TEXT, unit TEXT, collection_method TEXT, current_value TEXT, freshness_ttl_hours INTEGER, objective_direction TEXT);
CREATE TABLE IF NOT EXISTS metrics(node_id TEXT PRIMARY KEY REFERENCES nodes(id), formula TEXT, aggregation_window TEXT, thresholds_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(thresholds_json)), measured_at TEXT, value REAL);
CREATE TABLE IF NOT EXISTS signals(id TEXT PRIMARY KEY, metric_id TEXT REFERENCES nodes(id), subject_id TEXT REFERENCES nodes(id), severity TEXT, status TEXT, value REAL, rationale TEXT, observed_at TEXT DEFAULT CURRENT_TIMESTAMP, evidence_source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS initiatives(node_id TEXT PRIMARY KEY REFERENCES nodes(id), owner_node_id TEXT REFERENCES nodes(id), parent_initiative_id TEXT REFERENCES nodes(id), objective TEXT, scope TEXT, current_phase TEXT);
CREATE TABLE IF NOT EXISTS work_items(node_id TEXT PRIMARY KEY REFERENCES nodes(id), initiative_id TEXT REFERENCES nodes(id), parent_work_item_id TEXT REFERENCES nodes(id), assignee_id TEXT REFERENCES nodes(id), priority INTEGER, status TEXT NOT NULL DEFAULT 'backlog', acceptance_criteria TEXT, due_at TEXT, discovered_at TEXT DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS milestones(node_id TEXT PRIMARY KEY REFERENCES nodes(id), initiative_id TEXT REFERENCES nodes(id), target_at TEXT, acceptance_criteria TEXT, status TEXT DEFAULT 'planned');
CREATE TABLE IF NOT EXISTS decisions(node_id TEXT PRIMARY KEY REFERENCES nodes(id), initiative_id TEXT REFERENCES nodes(id), status TEXT CHECK(status IN('proposed','accepted','rejected','superseded')), rationale TEXT, decided_at TEXT, superseded_by TEXT REFERENCES nodes(id));
CREATE TABLE IF NOT EXISTS risks(node_id TEXT PRIMARY KEY REFERENCES nodes(id), initiative_id TEXT REFERENCES nodes(id), likelihood REAL, impact REAL, response TEXT, status TEXT);
CREATE TABLE IF NOT EXISTS queue_items(id TEXT PRIMARY KEY, work_item_id TEXT REFERENCES nodes(id), subject_id TEXT REFERENCES nodes(id), signal_id TEXT REFERENCES signals(id), kind TEXT NOT NULL, priority_score REAL, status TEXT NOT NULL DEFAULT 'open', reason TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coverage(id TEXT PRIMARY KEY, scope_node_id TEXT REFERENCES nodes(id), source_id TEXT REFERENCES sources(id), period_start TEXT, period_end TEXT, scan_state TEXT NOT NULL CHECK(scan_state IN('unscanned','partial','complete','blocked','not_applicable')), discovered_count INTEGER DEFAULT 0, imported_count INTEGER DEFAULT 0, gap_notes TEXT, scanned_at TEXT);
CREATE TABLE IF NOT EXISTS ingestion_batches(id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources(id), started_at TEXT, finished_at TEXT, status TEXT, records_seen INTEGER DEFAULT 0, records_inserted INTEGER DEFAULT 0, records_rejected INTEGER DEFAULT 0, error_log TEXT);
CREATE TABLE IF NOT EXISTS aliases(alias TEXT NOT NULL, node_id TEXT NOT NULL REFERENCES nodes(id), alias_kind TEXT DEFAULT 'name', PRIMARY KEY(alias,node_id));
CREATE VIRTUAL TABLE IF NOT EXISTS node_search USING fts5(id UNINDEXED, name, purpose, description);
CREATE TRIGGER IF NOT EXISTS nodes_ai AFTER INSERT ON nodes BEGIN INSERT INTO node_search(id,name,purpose,description) VALUES(new.id,new.name,new.purpose,new.description); END;
CREATE TRIGGER IF NOT EXISTS nodes_au AFTER UPDATE ON nodes BEGIN DELETE FROM node_search WHERE id=old.id; INSERT INTO node_search(id,name,purpose,description) VALUES(new.id,new.name,new.purpose,new.description); END;
CREATE TRIGGER IF NOT EXISTS nodes_ad AFTER DELETE ON nodes BEGIN DELETE FROM node_search WHERE id=old.id; END;